<script>const richSurface=document.querySelector('[data-rich-surface]');const richContent=document.querySelector('[data-rich-content]');document.querySelectorAll('[data-command]').forEach(button=>button.addEventListener('click',()=>{const command=button.dataset.command;if(command==='createLink'){const url=prompt('Enter link URL');if(url)document.execCommand(command,false,url);}else document.execCommand(command,false,button.dataset.value||null);richSurface.focus();}));const imageInput=document.querySelector('[data-image-input]');document.querySelector('[data-upload-image]')?.addEventListener('click',()=>imageInput.click());imageInput?.addEventListener('change',async()=>{if(!imageInput.files[0])return;const formData=new FormData();formData.append('image',imageInput.files[0]);const response=await fetch('{{ route('admin.blogs.upload-image') }}',{method:'POST',headers:{'X-CSRF-TOKEN':'{{ csrf_token() }}','Accept':'application/json'},body:formData});if(!response.ok){alert('Image upload failed. Please use an image smaller than 5 MB.');imageInput.value='';return;}const data=await response.json();richSurface.focus();document.execCommand('insertImage',false,data.url);imageInput.value='';});document.querySelector('[data-rich-form]')?.addEventListener('submit',event=>{richContent.value=richSurface.innerHTML;if(!richSurface.innerText.trim()&&!richSurface.querySelector('img')){event.preventDefault();alert('Please add some content before saving.');richSurface.focus();}});</script>
